# ORACLE_VECTORS_END

doAssert ingress32Vectors.len == 4096
doAssert ingress64Vectors.len == 4096
doAssert egress32Vectors.len == 4096
doAssert egress64Vectors.len == 4096

for vector in ingress32Vectors:
  let
    converted =
      toFloat256(
        cast[float32](vector.source)
      )
    actual =
      toBits(converted)

  doAssert actual.word3 == vector.word3
  doAssert actual.word2 == vector.word2
  doAssert actual.word1 == vector.word1
  doAssert actual.word0 == vector.word0
  doAssert cast[uint32](toFloat32(converted)) == vector.source

for vector in ingress64Vectors:
  let
    converted =
      toFloat256(
        cast[float64](vector.source)
      )
    actual =
      toBits(converted)

  doAssert actual.word3 == vector.word3
  doAssert actual.word2 == vector.word2
  doAssert actual.word1 == vector.word1
  doAssert actual.word0 == vector.word0
  doAssert cast[uint64](toFloat64(converted)) == vector.source

for vector in egress32Vectors:
  let value =
    fromBits(
      vector.word3,
      vector.word2,
      vector.word1,
      vector.word0,
    )

  doAssert cast[uint32](toFloat32(value)) == vector.expected

for vector in egress64Vectors:
  let value =
    fromBits(
      vector.word3,
      vector.word2,
      vector.word1,
      vector.word0,
    )

  doAssert cast[uint64](toFloat64(value)) == vector.expected

echo "F256_BINARY_FLOAT_INTEROP_CONTRACT_OK\t4096\t4096\t4096\t4096\t16384\t49"
